-- P3-04 (ADR-0031): check-ins — an append-only log of accepted check-in operations, keyed by the
-- client's operation id so a retried request is applied once (PRD §8 "client-generated operation
-- identifiers, server-side idempotency"). The day's current value stays in habit_occurrences.
-- Additive only: one enum type, one new table with its indexes, keys, CHECKs and an append-only
-- trigger; no existing table is altered.
-- Rollback before real data exists: drop habit_check_ins, its trigger function and the enum.
--
-- Generated by `prisma migrate diff`, then the constraints Prisma cannot express were added by
-- hand (kept in step with the shared limits by src/modules/habits/habits.schema.test.ts).
-- CreateEnum
CREATE TYPE "habit_check_in_action" AS ENUM ('set', 'skip', 'clear');

-- CreateTable
CREATE TABLE "habit_check_ins" (
    "id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "habit_id" UUID NOT NULL,
    "habit_type" "habit_type" NOT NULL,
    "operation_id" UUID NOT NULL,
    "local_date" DATE NOT NULL,
    "action" "habit_check_in_action" NOT NULL,
    "value" DECIMAL(12,3),
    "changed" BOOLEAN NOT NULL,
    "occurrence_version" INTEGER,
    "local_today" DATE NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "habit_check_ins_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "habit_check_ins_habit_id_local_date_idx" ON "habit_check_ins"("habit_id", "local_date");

-- CreateIndex
CREATE UNIQUE INDEX "habit_check_ins_user_id_operation_id_key" ON "habit_check_ins"("user_id", "operation_id");

-- AddForeignKey
ALTER TABLE "habit_check_ins" ADD CONSTRAINT "habit_check_ins_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "habit_check_ins" ADD CONSTRAINT "habit_check_ins_habit_id_user_id_habit_type_fkey" FOREIGN KEY ("habit_id", "user_id", "habit_type") REFERENCES "habits"("id", "user_id", "type") ON DELETE CASCADE ON UPDATE NO ACTION;


-- Hand-written: what Prisma cannot express.
-- Dates in the habit window; a value exactly for `set`, valid for the habit type (the same rule
-- as habit_occurrences_value_check); a clear leaves no record, a set or skip always does.
ALTER TABLE "habit_check_ins"
  ADD CONSTRAINT "habit_check_ins_dates_check" CHECK (
    "local_date" BETWEEN DATE '2000-01-01' AND DATE '2099-12-31'
    AND "local_today" BETWEEN DATE '2000-01-01' AND DATE '2099-12-31'
  ),
  ADD CONSTRAINT "habit_check_ins_value_check" CHECK (
    COALESCE(
      CASE
        WHEN "action" <> 'set' THEN "value" IS NULL
        ELSE "value" BETWEEN 0 AND 1000000 AND CASE "habit_type"
          WHEN 'binary' THEN "value" IN (0, 1)
          WHEN 'frequency' THEN "value" IN (0, 1)
          WHEN 'duration' THEN "value" <= 86400 AND "value" = trunc("value")
          WHEN 'negative' THEN "value" = trunc("value")
          ELSE TRUE
        END
      END,
      FALSE
    )
  ),
  ADD CONSTRAINT "habit_check_ins_occurrence_version_check" CHECK (
    COALESCE(
      CASE
        WHEN "action" = 'clear' THEN "occurrence_version" IS NULL
        ELSE "occurrence_version" >= 1
      END,
      FALSE
    )
  );

-- Append-only: a check-in is never edited (rows still disappear with their habit or account
-- through ON DELETE CASCADE, which is a DELETE, not an UPDATE).
CREATE FUNCTION "habit_check_ins_append_only"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'habit_check_ins rows are append-only' USING ERRCODE = 'check_violation';
END;
$$;

CREATE TRIGGER "habit_check_ins_no_update"
  BEFORE UPDATE ON "habit_check_ins"
  FOR EACH ROW EXECUTE FUNCTION "habit_check_ins_append_only"();
